137	func cloneResult(r *AdjustmentResult) *AdjustmentResult {
138		return &AdjustmentResult{
139			ID:                 r.ID,
140			CargoChanges:       append([]CargoChange(nil), r.CargoChanges...),
141			CompartmentChanges: append([]CompartmentChange(nil), r.CompartmentChanges...),
142		}
143	}
