38	// 真实配载唯一的落点逻辑：from 非空时从源集合删除，to 非空时加入目标
39	// 集合。from/to 为空字符串表示该侧不涉及任何舱位（未装载），相应集合
40	// 传 nil 即为无操作。调用方持锁。
41	func relocate(c *cargo, rt cargoRoute, fromSet, toSet map[string]*cargo) {
42		if rt.from != "" {
43			delete(fromSet, c.id)
44		}
45		if rt.to != "" {
