51	// 只影响原舱位，移动同时影响原舱位与目标舱位（交换中的两个舱位都会
52	// 纳入）。空舱位编号（未装载）不登记。
53	func touchedCompartments(affected map[string]bool, rt cargoRoute) {
54		if rt.from != "" {
55			affected[rt.from] = true
56		}
57		if rt.to != "" {
58			affected[rt.to] = true
59		}
60	}
