package stowage

// 本文件集中维护装载、卸下、移动三种操作的货物去向规则，使预演安排
// （Preview）、正式生效（Adjust）与货物变化记录三处共用同一份去向判断，
// 避免某一处修改后其他结果不同步。
//
// 去向只有三条：装载从未装载到目标舱位；卸下从原舱位回到未装载；
// 移动从原舱位到目标舱位。未装载一律以空舱位编号表示。

// cargoRoute 描述一件货物在一次调整中的去向：from 为原舱位、to 为
// 最终舱位，空字符串表示未装载。
type cargoRoute struct {
	from string
	to   string
}

// routeFor 是三种操作唯一的去向规则。调用方必须已完成逐条校验：
// 装载与移动的 target 非 nil，货物当前状态与操作种类相符；卸下忽略
// 目标值，target 为 nil 且不参与去向。
//
// 预演的货物变化记录、模拟配载落点与正式生效都由这里得到 from/to，
// 因此同一批安排在预览与正式提交中逐件货物的原舱位、最终舱位一致。
func routeFor(kind OpKind, current string, target *compartment) cargoRoute {
	switch kind {
	case OpLoad:
		return cargoRoute{from: "", to: target.id}
	case OpUnload:
		return cargoRoute{from: current, to: ""}
	case OpMove:
		return cargoRoute{from: current, to: target.id}
	}
	// 不可达：prepareOps 已拒绝无法识别的操作种类，routeFor 只会收到
	// 装载、卸下、移动三种之一。
	return cargoRoute{from: current, to: current}
}

// relocate 按去向把一件货物从源舱位集合移到目标舱位集合，是模拟配载与
// 真实配载唯一的落点逻辑：from 非空时从源集合删除，to 非空时加入目标
// 集合。from/to 为空字符串表示该侧不涉及任何舱位（未装载），相应集合
// 传 nil 即为无操作。调用方持锁。
func relocate(c *cargo, rt cargoRoute, fromSet, toSet map[string]*cargo) {
	if rt.from != "" {
		delete(fromSet, c.id)
	}
	if rt.to != "" {
		toSet[c.id] = c
	}
}

// touchedCompartments 按去向登记受影响舱位：装载只影响目标舱位，卸下
// 只影响原舱位，移动同时影响原舱位与目标舱位（交换中的两个舱位都会
// 纳入）。空舱位编号（未装载）不登记。
func touchedCompartments(affected map[string]bool, rt cargoRoute) {
	if rt.from != "" {
		affected[rt.from] = true
	}
	if rt.to != "" {
		affected[rt.to] = true
	}
}

// cargoSet 取登记处中某舱位当前的货物集合；空编号（未装载）返回 nil。
// 调用方持锁。
func (r *Registry) cargoSet(compartmentID string) map[string]*cargo {
	if compartmentID == "" {
		return nil
	}
	return r.compartments[compartmentID].cargo
}

package stowage

import "strings"

// AmendCargo 按货物编号更正一件货物的重量、目的地与混装许可。
//
// 编号与目的地沿用登记规则：去掉首尾空白后不得为空，编号区分大小写；
// weight 必须为正整数（千克）。空编号、货物不存在、非正重量或去空白后
// 目的地为空都按现有结构化错误拒绝；修改不存在的货物不会变成登记。
//
// 三项资料作为一次完整替换生效，内容与现有资料完全相同时同样成功，
// 但不新增货物、不再次占用重量。更正不占用配载调整编号，也不影响已
// 成功调整保存的结果：之后以原编号、原内容重复提交调整，仍返回首次
// 成功时的变化与重量。更正前返回的查询或预览快照继续保留原内容。
//
// 未装载货物只需资料本身合法，更正后仍为未装载。已装载货物按三项新
// 资料共同生效后的最终配载判断，不会因修改某个字段的中间状态不合法
// 而拒绝最终合法的资料：所属舱位先扣除该货物旧重量、再计入新重量，
// 恰好达到承重允许保存，超过承重或合计无法用 int64 表示则拒绝；
// 同舱目的地全部相同时允许不混装的货物共舱，出现不同目的地时所有
// 货物都必须允许混装。
//
// 更正失败时，货物的三项旧资料、所属舱位重量及其他货物全部保留。
func (r *Registry) AmendCargo(id string, weight int64, destination string, allowMixed bool) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	cid := strings.TrimSpace(id)
	if cid == "" {
		return fail(ErrInvalidID, "", "货物编号为空")
	}
	c, ok := r.cargos[cid]
	if !ok {
		return fail(ErrNotFound, cid, "货物 %s 不存在", cid)
	}
	if weight <= 0 {
		return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
	}
	dest := strings.TrimSpace(destination)
	if dest == "" {
		return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
	}

	// 已装载货物：在所属舱位的模拟配载上替换该货物，按三项资料共同
	// 生效后的最终状态统一判断，而不是逐个字段制造中间状态。
	if c.compartmentID != "" {
		comp := r.compartments[c.compartmentID]
		sim := &cargo{
			id:            c.id,
			weight:        weight,
			destination:   dest,
			allowMixed:    allowMixed,
			compartmentID: comp.id,
		}
		set := make(map[string]*cargo, len(comp.cargo))
		for otherID, other := range comp.cargo {
			if otherID == c.id {
				set[c.id] = sim
			} else {
				set[otherID] = other
			}
		}
		final := map[string]map[string]*cargo{comp.id: set}
		// 拒绝原因到结构化错误的转换与 Adjust 共用；更正不携带调整编号。
		if rej := r.firstRejection(final); rej != nil {
			return rejectionError(rej, fail)
		}
	}

	c.weight = weight
	c.destination = dest
	c.allowMixed = allowMixed
	return nil
}

// Package stowage 提供本地舱单与配载能力：
// 登记舱位与货物、执行多货物的装卸调整、预览调整结果、更正货物资料，
// 并可随时查询配载状态。
//
// 舱位以唯一编号和最大承重（正整数千克）标识；货物以唯一编号、
// 重量（正整数千克）、目的地及是否允许混装标识。货物登记后处于
// 未装载状态，可通过调整进行装载、卸下或移动。AmendCargo 可在货物
// 编号与所属舱位不变的前提下整体替换其重量、目的地与混装许可；已
// 装载货物按三项资料共同生效后的最终配载校验，更正不占用调整编号。
//
// 一次调整可包含多件货物的操作，全部操作按完成后的最终配载统一
// 校验：舱位总重量不得超过承重；不同目的地货物共舱时所有货物都
// 必须允许混装。任一操作不合法，整次调整不生效。
//
// Preview 在不改变任何状态的前提下预演同一批操作，给出能否提交、
// 涉及货物的原舱位与预计舱位、受影响舱位前后完整配载，以及全部
// 拒绝原因；正式提交仍以 Adjust 提交时的状态重新判断。
package stowage

// Ready 表示基线可以运行。
func Ready() bool { return true }

