package stowage

import "testing"

func TestScratchStateBeforeTarget(t *testing.T) {
	r := NewRegistry()
	mustRegisterCompartment(t, r, "C1", 100)
	mustRegisterCargo(t, r, "GL", 10, "X", true) // 已装载
	mustRegisterCargo(t, r, "GU", 10, "X", true) // 未装载
	mustAdjust(t, r, "init", []Op{{Kind: OpLoad, CargoID: "GL", Target: "C1"}})

	for _, tc := range []struct {
		name string
		op   Op
	}{
		{"已装载再装载-空目标", Op{Kind: OpLoad, CargoID: "GL", Target: "  "}},
		{"已装载再装载-不存在目标", Op{Kind: OpLoad, CargoID: " GL ", Target: " NOPE "}},
		{"未装载移动-空目标", Op{Kind: OpMove, CargoID: "GU", Target: "  "}},
		{"未装载移动-不存在目标", Op{Kind: OpMove, CargoID: " GU ", Target: " NOPE "}},
	} {
		// Preview
		pv, err := r.Preview([]Op{tc.op})
		se := requireError(t, err, ErrStateMismatch)
		if pv != nil {
			t.Fatalf("%s: 预览不应返回局部结果", tc.name)
		}
		if se.ID != "GL" && se.ID != "GU" {
			t.Fatalf("%s: 错误编号应为去空白后货物编号, got %q", tc.name, se.ID)
		}
		// Adjust
		se2 := submitExpectReject(t, r, "a-"+tc.name, []Op{tc.op})
		if se2.Kind != ErrStateMismatch {
			t.Fatalf("%s: Adjust 应先报状态不符, got %s", tc.name, se2.Kind)
		}
	}

	// 状态合法后，空目标/不存在目标才报目标错误。
	if _, err := r.Preview([]Op{{Kind: OpLoad, CargoID: "GU", Target: "  "}}); err == nil {
		t.Fatal("未装载货物装空目标应被拒")
	} else if se := requireError(t, err, ErrInvalidID); se.ID != "" {
		t.Fatalf("空目标错误编号应为空, got %q", se.ID)
	}
	se := requireError(t, r.Adjust("bad", []Op{{Kind: OpLoad, CargoID: " GU ", Target: " NOPE "}}).(error), ErrNotFound)
	if se.ID != "NOPE" || se.AdjustmentID != "bad" {
		t.Fatalf("不存在目标应指向 NOPE 且带编号, got %+v", se)
	}
}
EOF
